import{_ as e,a as d,o as a,a6 as o}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Catalog Category — Detail (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-category-detail","title":"Category Detail (with all translations)","description":"Fetch a single category by ID including the full translations array (all locales present in the DB) and the list of filterable attribute IDs.","query":"query AdminCatalogCategory($id: ID!) {\\n  adminCategory(id: $id) {\\n    id\\n    _id\\n    name\\n    slug\\n    status\\n    position\\n    parentId\\n    displayMode\\n    logoUrl\\n    bannerUrl\\n    description\\n    locale\\n    createdAt\\n    updatedAt\\n    translations\\n    filterableAttributeIds\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/admin/catalog/categories/7\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminCategory\\": {\\n      \\"id\\": \\"/api/admin/catalog/categories/7\\",\\n      \\"_id\\": 7,\\n      \\"name\\": \\"Apparel\\",\\n      \\"slug\\": \\"apparel\\",\\n      \\"status\\": 1,\\n      \\"position\\": 1,\\n      \\"parentId\\": 1,\\n      \\"displayMode\\": \\"products_and_description\\",\\n      \\"logoUrl\\": \\"https://example.com/storage/category/7/logo.webp\\",\\n      \\"bannerUrl\\": null,\\n      \\"description\\": \\"Men's and women's apparel\\",\\n      \\"locale\\": \\"en\\",\\n      \\"createdAt\\": \\"2026-01-12T08:15:00+00:00\\",\\n      \\"updatedAt\\": \\"2026-04-30T14:20:09+00:00\\",\\n      \\"translations\\": [\\n        {\\n          \\"locale\\": \\"en\\",\\n          \\"name\\": \\"Apparel\\",\\n          \\"slug\\": \\"apparel\\",\\n          \\"description\\": \\"Men's and women's apparel\\",\\n          \\"metaTitle\\": null,\\n          \\"metaDescription\\": null,\\n          \\"metaKeywords\\": null\\n        },\\n        {\\n          \\"locale\\": \\"fr\\",\\n          \\"name\\": \\"Vêtements\\",\\n          \\"slug\\": \\"vetements\\",\\n          \\"description\\": null,\\n          \\"metaTitle\\": null,\\n          \\"metaDescription\\": null,\\n          \\"metaKeywords\\": null\\n        }\\n      ],\\n      \\"filterableAttributeIds\\": [11, 23]\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/categories/categories-detail.md","filePath":"api/graphql-api/admin/catalog/categories/categories-detail.md","lastUpdated":1787290888000}`),r={name:"api/graphql-api/admin/catalog/categories/categories-detail.md"};function n(i,t,l,c,s,g){return a(),d("div",null,t[0]||(t[0]=[o('<h1 id="catalog-category-—-detail-graphql" tabindex="-1">Catalog Category — Detail (GraphQL) <a class="header-anchor" href="#catalog-category-—-detail-graphql" aria-label="Permalink to &quot;Catalog Category — Detail (GraphQL)&quot;">​</a></h1><p>GraphQL item query that returns a single category by its IRI, including the <strong>full translations array</strong> (every locale present in the database) and the list of <strong>filterable attribute IDs</strong> configured for the category.</p><p>This is the query to call when an admin needs complete metadata for a category — e.g. when pre-populating the edit form in Catalog → Categories.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>adminCategory</code></td><td>Query (item)</td></tr></tbody></table><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>Yes</td><td>API Platform IRI of the category (e.g. <code>&quot;/api/admin/catalog/categories/7&quot;</code>)</td></tr></tbody></table><p>Take the IRI straight from the <code>id</code> of an <a href="/api/graphql-api/admin/catalog/categories/categories-listing.html"><code>adminCategories</code></a> edge node, or build it as <code>/api/admin/catalog/categories/&lt;numericId&gt;</code>. A tree node&#39;s <code>id</code> will not work — that one resolves to <code>/api/admin/admin_category_trees/&lt;id&gt;</code>, so use its <code>_id</code> to build the path.</p><h2 id="node-fields" tabindex="-1">Node Fields <a class="header-anchor" href="#node-fields" aria-label="Permalink to &quot;Node Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>API Platform IRI (e.g. <code>/api/admin/catalog/categories/7</code>)</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Raw category ID</td></tr><tr><td><code>name</code></td><td><code>String</code></td><td>Category name in the current app locale</td></tr><tr><td><code>slug</code></td><td><code>String</code></td><td>URL slug in the current app locale</td></tr><tr><td><code>status</code></td><td><code>Int</code></td><td><code>1</code> = enabled, <code>0</code> = disabled</td></tr><tr><td><code>position</code></td><td><code>Int</code></td><td>Display order position</td></tr><tr><td><code>parentId</code></td><td><code>Int</code></td><td>Parent category ID; <code>null</code> for root nodes</td></tr><tr><td><code>displayMode</code></td><td><code>String</code></td><td>Category display mode (e.g. <code>products_and_description</code>)</td></tr><tr><td><code>logoUrl</code></td><td><code>String</code></td><td>Storage URL for the category logo; <code>null</code> if not set</td></tr><tr><td><code>bannerUrl</code></td><td><code>String</code></td><td>Storage URL for the category banner; <code>null</code> if not set</td></tr><tr><td><code>description</code></td><td><code>String</code></td><td>Category description in the current app locale</td></tr><tr><td><code>locale</code></td><td><code>String</code></td><td>App locale used for top-level scalar fields</td></tr><tr><td><code>createdAt</code></td><td><code>String</code></td><td>ISO 8601 creation timestamp</td></tr><tr><td><code>updatedAt</code></td><td><code>String</code></td><td>ISO 8601 last-update timestamp</td></tr><tr><td><code>translations</code></td><td>scalar (JSON array)</td><td>All locale translations (see below)</td></tr><tr><td><code>filterableAttributeIds</code></td><td>scalar (JSON array)</td><td>Integer IDs of filterable attributes configured for this category</td></tr></tbody></table><h3 id="translations-item-shape" tabindex="-1"><code>translations</code> item shape <a class="header-anchor" href="#translations-item-shape" aria-label="Permalink to &quot;`translations` item shape&quot;">​</a></h3><p><code>translations</code> is returned as a <strong>plain JSON array</strong> (scalar in GraphQL). Each element corresponds to one locale row in <code>category_translations</code>:</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>locale</code></td><td>string</td><td>Locale code (e.g. <code>en</code>, <code>fr</code>)</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Category name in this locale</td></tr><tr><td><code>slug</code></td><td>string|null</td><td>URL slug in this locale</td></tr><tr><td><code>description</code></td><td>string|null</td><td>Description in this locale</td></tr><tr><td><code>metaTitle</code></td><td>string|null</td><td>SEO meta title</td></tr><tr><td><code>metaDescription</code></td><td>string|null</td><td>SEO meta description</td></tr><tr><td><code>metaKeywords</code></td><td>string|null</td><td>SEO meta keywords</td></tr></tbody></table><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td>Unknown or deleted id</td><td>HTTP <code>200</code> with <code>Category not found.</code> in <code>errors[]</code> and <code>null</code> in <code>data.adminCategory</code></td></tr><tr><td>Missing or invalid token</td><td>HTTP <code>401</code> with <code>{&quot;message&quot;: &quot;Unauthenticated.&quot;, &quot;error&quot;: &quot;unauthenticated&quot;}</code> — rejected by the transport before GraphQL runs</td></tr></tbody></table><h2 id="working-with-this-query" tabindex="-1">Working With This Query <a class="header-anchor" href="#working-with-this-query" aria-label="Permalink to &quot;Working With This Query&quot;">​</a></h2><ul><li><strong><code>translations</code> and <code>filterableAttributeIds</code> are JSON scalars.</strong> Select each as a <strong>bare field</strong> — a sub-selection is a schema error. The whole structure comes back in one piece.</li><li><strong><code>translations</code> carries one entry per stored locale row</strong>, not just the requested one, so a multi-locale store returns them all. Unset text fields come back as the empty string <code>&quot;&quot;</code>, not <code>null</code>.</li><li><strong>The top-level <code>name</code>, <code>slug</code>, and <code>description</code> duplicate the requested locale&#39;s entry.</strong> They are a shortcut, not extra data — <code>locale</code> tells you which entry they came from.</li><li><strong><code>filterableAttributeIds</code> is a flat integer array.</strong> <code>[]</code> means none are configured; it is the layered-navigation attribute set for this category, not the products&#39; attributes.</li><li><strong>The <code>id</code> argument is the IRI, not the number.</strong> Build it as <code>/api/admin/catalog/categories/&lt;_id&gt;</code> or pass a listing edge&#39;s <code>id</code> straight through.</li></ul>',17)]))}const u=e(r,[["render",n]]);export{p as __pageData,u as default};
